INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-202', '11', 'Sustainability', 'Cross-cutting', '🔴 必考 Must Know', 'All', '可持续性整合', 'Sustainability Integration', '在治理、规划、质量、采购、风险和价值中持续考虑', '不是收尾报告附录', 'index_only');
