INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-204', '11', 'Sustainability', 'Cross-cutting', '🟠 高频 High Frequency', 'All', '三重底线', 'People, Planet, Prosperity', '平衡社会、环境与经济价值', '不能只用短期财务指标', 'index_only');
INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-205', '11', 'Sustainability', 'Cross-cutting', '🔴 必考 Must Know', 'All', '可持续采购', 'Sustainable Procurement', '把供应链环境、社会、治理和全寿命成本纳入选择', '最低报价未必最佳价值', 'brief');
INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-206', '11', 'Sustainability', 'Cross-cutting', '🟠 高频 High Frequency', 'All', '碳与资源指标', 'Carbon and Resource Metrics', '建立基线、边界、数据来源和改进目标', '指标边界不清会误导', 'brief');
INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-207', '11', 'Sustainability', 'Cross-cutting', '🟠 高频 High Frequency', 'All', '社会影响', 'Social Impact', '考虑安全、公平、可及性、社区和劳工影响', '合规只是最低线', 'index_only');
INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-208', '11', 'Sustainability', 'Cross-cutting', '🔴 必考 Must Know', 'All', '可持续性风险', 'Sustainability Risk', '识别环境、社会、供应链、监管与声誉不确定性', '既有威胁也有机会', 'index_only');
INSERT INTO knowledge_points (id, chapter_id, domain, task, priority, approach, title_zh, title_en, exam_focus, common_trap, content_coverage) VALUES ('KP-209', '11', 'Sustainability', 'Cross-cutting', '🟠 高频 High Frequency', 'All', '净正向价值', 'Net-positive Value', '追求超越减害的再生或正向结果', '需可衡量且防止绿色漂洗', 'index_only');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FOUND-001', '某物流公司在三周节庆期间每天按同一流程分拣包裹，节后取消夜班。这项夜班安排最准确的分类是什么？', '{"A":"项目，因为只有三周","B":"运营，因为核心工作是重复维持业务","C":"项目群，因为涉及多班组","D":"无法判断，因为没有预算"}', 'Foundation', 'F', 'All', '中', 'Temporary ≠ Project');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FOUND-001', 'B', '临时安排并不自动构成项目；工作本质是重复分拣并维持运营。A 把 temporary 误当成 project，C/D 与定义无关。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FOUND-002', '企业决定在六个月内设计并部署新的仓储机器人系统，完成验收后交给运营团队维护。这段‘设计并部署’是什么？', '{"A":"项目","B":"运营","C":"项目组合","D":"持续改进例会"}', 'Foundation', 'F', 'All', '易', '把长期使用误判为运营');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FOUND-002', 'A', '它有独特成果、完成状态和移交点。上线后的重复维护才属于运营。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FOUND-003', '公司每年为不同城市举办一次新品发布会。哪项最准确？', '{"A":"因为每年重复，所以一定是运营","B":"每场可作为独立项目，因为地点、干系人和目标情境独特","C":"全部只能算项目组合","D":"只有首次才是项目"}', 'Foundation', 'F', 'All', '中', '重复 ≠ 运营');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FOUND-003', 'B', '重复开展相似工作不排除每次都是独特项目；关键看具体情境和完成状态。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FOUND-004', '软件按期上线且未超预算，但用户采用率仅为计划的 10%。最合理的判断是？', '{"A":"项目必然成功，因为三重约束达标","B":"项目必然失败，因为任何收益都应在收尾前实现","C":"需按既定成果和收益指标评估价值，并明确后续收益责任","D":"只需增加范围"}', 'Foundation', 'F', 'All', '中', 'Deliverable ≠ Outcome ≠ Benefit');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FOUND-004', 'C', '2026 强调价值和成果。三重约束不足以单独判定成功；部分收益可能在运营期实现，但必须有指标和责任人。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FOUND-005', '监管文档要求稳定，但产品界面需求需每两周接受用户反馈。最合适的总体方法是？', '{"A":"全预测型，禁止界面变化","B":"全敏捷，忽略阶段审批","C":"混合型：治理文档预测规划，界面迭代交付并管理接口","D":"先不选择任何方法"}', 'Process', 'PR1', 'Hybrid', '中', 'Hybrid 不是机械各半');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FOUND-005', 'C', '工作性质不同，Hybrid 可同时满足治理证据和快速反馈；关键是统一接口、风险和价值。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-RISK-001', '风险登记册中记录的供应商停产触发条件今天已经发生。PM 下一步最应做什么？', '{"A":"继续只监控概率","B":"把它当 Issue，执行已批准响应并更新相关记录","C":"删除该风险","D":"等下次月报"}', 'Business Environment', 'BE4/BE5', 'All', '中', 'Risk 与 Issue 时间状态');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-RISK-001', 'B', '触发后风险成为已发生问题，应执行预案、登记 Issue、沟通影响并持续跟踪。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-RISK-002', '团队购买保险以应对设备损坏。哪项最准确？', '{"A":"风险已消失","B":"这是 Transfer，但仍可能有免赔额、延迟等残余风险","C":"这是 Avoid","D":"这是 Exploit"}', 'Business Environment', 'BE5', 'Predictive', '易', 'Transfer ≠ Eliminate');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-RISK-002', 'B', '保险转移部分财务后果，不消除事件或全部影响。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-RISK-003', '为降低网络攻击风险，团队启用多因素认证；因此部分用户可能流失。用户流失属于什么？', '{"A":"残余风险","B":"次生风险","C":"机会","D":"已知问题"}', 'Business Environment', 'BE5', 'All', '中', 'Secondary vs Residual');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-RISK-003', 'B', '它由风险响应产生，是 Secondary Risk；攻击仍可能发生的部分才是 Residual Risk。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-RISK-004', '一个从未识别的关键接口故障已经造成停机。没有预案。PM 应把临时修复措施称为什么？', '{"A":"Contingency Plan","B":"Workaround","C":"Risk Appetite","D":"Scope Baseline"}', 'Business Environment', 'BE4', 'All', '中', '预案与权变');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-RISK-004', 'B', '对未识别或无预案的已发生问题采取的临时响应是 Workaround。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-RISK-005', '一个威胁超出项目权限并由企业安全委员会拥有。PM 最适合采用哪种策略？', '{"A":"Accept 并停止记录","B":"Escalate，并管理移交接口和持续沟通","C":"Exploit","D":"自行更改企业政策"}', 'Business Environment', 'BE5', 'All', '中', '升级不是甩手');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-RISK-005', 'B', '超出范围/权限的风险应升级到适当层级，但项目仍需跟踪其接口影响。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-CHANGE-001', '预测型项目中，客户提出‘只改一个小字段’。PM first 应做什么？', '{"A":"让团队立即改","B":"记录变更并分析对基准、风险和价值的影响","C":"直接拒绝所有变化","D":"等项目结束"}', 'Business Environment', 'BE3', 'Predictive', '易', '小变更也需控制');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-CHANGE-001', 'B', '大小不改变基本控制逻辑：先记录和影响分析，再按授权审批。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-CHANGE-002', '变更已由有权限机构批准。PM 下一步最合适的是？', '{"A":"更新相关计划/基准和沟通后实施","B":"再次当作未批准请求","C":"只口头通知一名成员","D":"不记录直接上线"}', 'Business Environment', 'BE3', 'Predictive', '中', '批准 ≠ 自动实施完成');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-CHANGE-002', 'A', '批准后需反映到受影响文件和工作授权，再实施并验证。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-CHANGE-003', 'Sprint 第三天，一名高管要求加入新报表。团队判断它不影响当前 Sprint Goal。应怎么做？', '{"A":"PM 直接塞进 Sprint Backlog","B":"交给 PO 进入 Product Backlog 并排序，除非团队自愿协商调整","C":"永久拒绝","D":"提交 CCB 后立即中断 Sprint"}', 'Business Environment', 'BE3', 'Agile', '中', '预测型变更流程套敏捷');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-CHANGE-003', 'B', '敏捷变化通常进入 Product Backlog，由 PO 排序；Sprint Backlog 由 Developers 管理。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-CHANGE-004', '客户希望下月开始获得收益，而完整产品还需八个月。最佳做法是？', '{"A":"坚持全部范围完成后一次交付","B":"与干系人识别高价值可用增量并重新排序","C":"删除质量活动","D":"提高团队加班"}', 'Process', 'PR3', 'All', '中', '增量不是半成品');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-CHANGE-004', 'B', '价值导向要求寻找可用、合规且有质量的增量，先验证商业价值。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-CHANGE-005', '下列哪项最符合 MVP？', '{"A":"缺陷最多但最快发布的版本","B":"具备最小可用能力、能验证关键价值假设的版本","C":"所有功能的低保真原型","D":"不需要验收标准的版本"}', 'Process', 'PR3', 'Agile', '易', 'MVP ≠ 最低质量');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-CHANGE-005', 'B', 'MVP 的核心是以最小可用产品验证价值，并仍需满足必要质量与合规。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-AGILE-001', 'Daily Scrum 中，Scrum Master 正在逐人分配当天任务。最主要的问题是什么？', '{"A":"会议时间太短","B":"削弱 Developers 的自管理，Daily Scrum 应由其检查目标并调整计划","C":"PO 没有参加","D":"必须改成周会"}', 'Agile', 'Cross-cutting', 'Agile', '中', 'Servant Leadership 不是指挥控制');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-AGILE-001', 'B', 'Developers 对如何完成 Sprint 工作负责；Scrum Master 促进而非分配。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-AGILE-002', '一个条目满足自己的 Acceptance Criteria，但自动化安全扫描未达到团队 DoD。它是什么状态？', '{"A":"Done","B":"未 Done，不能计入可用 Increment","C":"只要 PO 同意就是 Done","D":"自动进入下个版本且算完成"}', 'Agile', 'Cross-cutting', 'Agile', '中', 'AC vs DoD');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-AGILE-002', 'B', 'DoD 是所有增量共同质量标准，单条验收标准不能替代它。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-AGILE-003', '哪一事件主要检查产品成果、外部变化并与干系人调整 Product Backlog？', '{"A":"Sprint Review","B":"Sprint Retrospective","C":"Daily Scrum","D":"Backlog Refinement"}', 'Agile', 'Cross-cutting', 'Agile', '易', 'Review vs Retro');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-AGILE-003', 'A', 'Review 面向产品与价值；Retrospective 面向团队过程改进。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-AGILE-004', '团队把 WIP Limit 设为 3，当前已有 3 个条目进行中。最符合 Kanban 的动作是？', '{"A":"再开始两个以提高利用率","B":"帮助完成或解除现有工作阻塞，再拉取新工作","C":"取消限制","D":"增加个人绩效排名"}', 'Agile', 'Cross-cutting', 'Agile', '中', '忙碌不等于流动');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-AGILE-004', 'B', 'WIP Limit 促进完成、暴露瓶颈并减少切换。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-AGILE-005', '管理层想用不同团队的 Story Point 比较绩效。PM 应如何回应？', '{"A":"同意，点数是标准工时","B":"说明点数是团队内部相对尺度，改用成果、价值和流动指标","C":"把所有点乘以 8 小时","D":"要求高绩效团队提高估算"}', 'Agile', 'Cross-cutting', 'Agile', '中', 'Story Points ≠ hours/KPI');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-AGILE-005', 'B', 'Story Point 的尺度依赖团队，不适合跨团队绩效排名。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-EVM-001', '状态日 PV=90、EV=80、AC=100。哪项正确？', '{"A":"进度领先且低于预算","B":"进度落后且超预算","C":"进度领先但超预算","D":"仅凭这些数无法判断任何状态"}', 'Process', 'PR6', 'Predictive', '易', 'EV 必须做分子/被减数');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-EVM-001', 'B', 'SV=80-90=-10，SPI<1；CV=80-100=-20，CPI<1。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-EVM-002', '项目必须缩短两周，且不得增加预算。PM first 应检查什么？', '{"A":"非关键路径全部加人","B":"关键路径上可否安全重叠活动及其新增风险","C":"所有活动减少质量检查","D":"直接压缩基准"}', 'Process', 'PR8', 'Predictive', '中', '先找关键路径');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-EVM-002', 'B', '预算受限时可评估 Fast Tracking，但只对影响总工期的路径有意义，并需分析风险。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-EVM-003', '一个资源在两项关键活动间冲突，且没有可用浮动。使用 Resource Leveling 最可能怎样？', '{"A":"一定不改变工期","B":"可能改变关键路径和完工日期","C":"只改变成本基准","D":"等同于 Smoothing"}', 'Process', 'PR4', 'Predictive', '中', 'Leveling vs Smoothing');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-EVM-003', 'B', 'Leveling 为解决资源约束可移动活动，可能影响工期；Smoothing 才受浮动限制。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-EVM-004', 'BAC=200，EV=100，AC=125；假设当前成本效率会持续，EAC 最合适为？', '{"A":"160","B":"200","C":"250","D":"325"}', 'Process', 'PR6', 'Predictive', '中', '先说明偏差持续假设');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-EVM-004', 'C', 'CPI=100/125=0.8；EAC=BAC/CPI=250。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-EVM-005', '哪项关于关键路径最准确？', '{"A":"由持续时间最长的单个活动组成","B":"是网络中总持续时间最长、决定最短工期的路径","C":"永远只有一条且浮动永远为零","D":"任何活动延误都必然延误项目"}', 'Process', 'PR8', 'Predictive', '易', '单活动 vs 路径');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-EVM-005', 'B', '关键路径看路径总时长；可有多条，受约束时浮动也可能为负。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FUT-001', '团队想把客户投诉原文上传到未批准的公共 AI 工具做分类。PM first 应做什么？', '{"A":"立即上传，效率优先","B":"暂停并评估隐私、保密、政策和获批替代方案","C":"删除项目风险登记册","D":"只让实习生操作"}', 'AI', 'Cross-cutting', 'All', '中', '便利不能绕过数据治理');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FUT-001', 'B', '敏感数据和未批准工具带来隐私、安全与合规风险，应先评估并选择受控方案。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FUT-002', 'AI 建议删除两个质量检查点以缩短进度。最佳做法是？', '{"A":"按建议自动执行","B":"由有权限人员验证数据、风险、合规和价值后再决策","C":"因为是 AI 建议所以永久拒绝","D":"隐藏建议来源"}', 'AI', 'Cross-cutting', 'All', '中', 'Human oversight');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FUT-002', 'B', 'AI 可增强分析，但高影响变更需人类监督、证据和正式治理。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FUT-003', '供应商模型整体准确率高，但对少数语言用户错误率明显更高。项目经理应关注什么？', '{"A":"只看整体平均数","B":"群体偏差、公平影响及纠正和监控措施","C":"提高 Story Points","D":"把问题归为范围蔓延"}', 'AI', 'Cross-cutting', 'All', '中', '平均值掩盖偏差');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FUT-003', 'B', '平均准确率可能掩盖对特定群体的不公平，需要分群验证与治理。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FUT-004', '两种材料初始价格不同：便宜材料在十年运营期能耗和更换频率更高。最佳比较方式是？', '{"A":"只比采购价","B":"比较全生命周期成本、环境社会影响、风险和价值","C":"只看项目工期","D":"由供应商自行决定"}', 'Sustainability', 'Cross-cutting', 'All', '中', 'Lowest price vs Best value');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FUT-004', 'B', '生命周期思维避免把交付期节省转化为长期成本和影响。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('KP-FUT-005', '项目宣称‘碳中和’，但没有说明组织边界、基线、数据来源和抵消方式。主要问题是？', '{"A":"文案不够简短","B":"指标不可审计，存在误导和绿色漂洗风险","C":"范围一定过大","D":"一定违反 Scrum"}', 'Sustainability', 'Cross-cutting', 'All', '中', 'Greenwashing');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('KP-FUT-005', 'B', '可持续性声明需清晰边界、可靠数据、方法和复核。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-001', '虚拟团队成员因时区问题经常错过决定，并开始抵触项目。PM first 应做什么？', '{"A":"替换成员","B":"与相关成员了解沟通需求并共同调整沟通策略和反馈机制","C":"要求所有人按总部时间","D":"报告给客户"}', 'People', 'P4/P8', 'All', '中', '先协作再升级');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PEO-001', 'B', '先分析沟通需求和根因，再裁剪渠道与节奏。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-002', '两位负责人对优先级冲突，双方都有合理数据。最佳长期做法是？', '{"A":"强迫其中一方接受","B":"促进双方围绕共同愿景和事实合作解决","C":"回避直到延期","D":"随机选择"}', 'People', 'P1/P2', 'All', '中', 'Collaborate');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PEO-002', 'B', '协作解决能处理根因并对齐共同价值。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-003', '新成员缺少关键技能但学习意愿高。PM 最合适的领导反应是？', '{"A":"直接解雇","B":"提供辅导、结对和清晰期望，并跟踪进展","C":"完全放任","D":"隐藏问题"}', 'People', 'P3/P7', 'All', '中', 'Empower ≠ abandon');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PEO-003', 'B', '情境领导结合能力和意愿，既支持又明确责任。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-004', '发起人与客户对成功含义不同。PM first 应？', '{"A":"采用发起人定义","B":"显化双方期望并促进讨论，形成可衡量的共同成功标准","C":"推迟到收尾","D":"由团队投票"}', 'People', 'P1/P5/P6', 'All', '中', '不能单边承诺');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PEO-004', 'B', '需要对齐期望和愿景，并把标准纳入治理。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-005', '项目即将移交，唯一架构师掌握未记录的关键知识。最佳措施是？', '{"A":"只要求上传旧邮件","B":"安排结对、演示、文档和接收方验证","C":"等离职后再处理","D":"把风险删除"}', 'People', 'P7', 'All', '中', '上传文件 ≠ 转移完成');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PEO-005', 'B', '隐性和显性知识需多种方式转移并验证接收。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PEO-006', '团队成员在回顾会上指出估算流程问题，主管当众责备他。PM 应优先保护什么？', '{"A":"主管权威","B":"心理安全和基于事实的改进讨论","C":"会议记录格式","D":"个人排名"}', 'People', 'P3', 'Agile', '中', '不把回顾变成追责');
