INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-001', '客户正式拒收一个技术检验合格的交付物，因为未满足约定业务验收条件。说明什么？', '{"A":"Control Quality 可替代 Validate Scope","B":"技术正确不等于客户正式接受","C":"验收标准不重要","D":"必须取消项目"}', 'Process', 'PR2/PR7', 'Predictive', '中', 'QC vs Validate Scope');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PRO-001', 'B', '质量控制和范围确认目的不同。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-002', '关键路径活动延迟三天，总浮动为零。最直接影响是什么？', '{"A":"项目完工可能延迟三天，除非采取恢复措施","B":"一定不影响项目","C":"只影响成本","D":"自动改变范围"}', 'Process', 'PR8', 'Predictive', '易', '关键路径');
