INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-003', '团队为了提高完成条目数，拆小 Story 并降低 DoD。哪个指标最可能被游戏化？', '{"A":"Velocity","B":"法规条款","C":"合同类型","D":"组织文化"}', 'Process', 'PR9', 'Agile', '中', '指标成为目标');
