INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-004', '供应商报低价但有严重交付和劳工风险。选择时应？', '{"A":"只选最低价","B":"依据采购策略比较全寿命价值、风险、质量、合规与可持续性","C":"取消所有外购","D":"忽略历史绩效"}', 'Process', 'PR5', 'All', '中', '最低价偏误');
