INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-005', '一个已识别风险发生后使用应急储备。哪项正确？', '{"A":"应急储备用于已识别风险，通常在成本基准内","B":"它等同管理储备","C":"无需记录","D":"一定要取消项目"}', 'Process', 'PR6', 'Predictive', '易', '两类储备');
