INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-PRO-006', '开发团队希望用两周 Spike 调研未知技术。PO 应关注什么？', '{"A":"让研究无限持续","B":"明确时间盒、学习目标和将如何影响 Backlog 决策","C":"把 Spike 当作已交付价值","D":"取消验收标准"}', 'Process', 'PR1/PR3', 'Agile', '中', '研究不是无限范围');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-PRO-006', 'B', 'Spike 用于减少不确定性，需有边界和输出。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-001', '法规更新使当前方案明天起违法。PM first 应？', '{"A":"继续直到 CCB 月会","B":"立即保护人员/停止不合规活动，评估影响并按治理紧急升级和变更","C":"隐藏变化","D":"让供应商决定"}', 'Business Environment', 'BE2/BE3/BE8', 'All', '难', '合规紧急例外');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-BE-001', 'B', '强制合规是常规‘先分析再行动’的安全例外，但仍需记录、评估和治理。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-002', '市场已转向替代技术，项目商业价值大幅下降。治理委员会应获得什么？', '{"A":"只报告沉没成本","B":"更新的价值、风险、选项和建议，以支持继续/调整/终止决策","C":"只报告团队士气","D":"隐藏外部变化"}', 'Business Environment', 'BE8', 'All', '难', 'Sunk cost');
