INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-003', '项目经理无权批准超过 5% 预算的变更。最合适做法是？', '{"A":"拆成小变更规避阈值","B":"完成影响分析并按升级路径提交授权机构","C":"自行批准","D":"让团队口头同意"}', 'Business Environment', 'BE1/BE3', 'Predictive', '中', '治理权限');
