INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-004', '问题反复发生，团队每次只做临时修复。下一步应强化什么？', '{"A":"增加 Workaround 数量","B":"根因分析、持续改进和 OPA 更新","C":"减少透明度","D":"删除 Issue Log"}', 'Business Environment', 'BE4/BE6', 'All', '中', '症状 vs 根因');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('CH-BE-004', 'B', '反复问题说明需从临时修复转向系统性改进。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-005', '组织发布新流程但采用率低。哪项最有帮助？', '{"A":"只重复发送邮件","B":"评估文化和受影响角色，开展参与、培训、支持与采用度量","C":"宣布项目已成功","D":"把所有抵触者移除"}', 'Business Environment', 'BE7', 'All', '中', '上线 ≠ 采用');
