INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('CH-BE-006', '风险所有人已离开组织。PM best 应？', '{"A":"保留原名字以免修改","B":"重新分配有能力和权限的所有人，沟通并更新登记册","C":"删除风险","D":"等风险发生"}', 'Business Environment', 'BE5', 'All', '易', '记录必须保持有效');
