INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-001', '混合项目的硬件供应商延期，软件团队仍可开发模拟接口。PM first 应？', '{"A":"让所有软件工作停止","B":"评估依赖、接口风险和可并行价值，更新综合计划","C":"立即终止供应商合同","D":"隐藏延期"}', 'Process', 'PR1/PR5', 'Hybrid', '难', '局部问题需整体分析');
