INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-002', '客户要求团队在验收前跳过强制安全测试。PM 应？', '{"A":"满足客户","B":"拒绝绕过强制要求，说明影响并按合规治理处理","C":"让团队匿名决定","D":"测试后补文件"}', 'Business Environment', 'BE2', 'All', '中', 'Customer value ≠ ignore compliance');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-002', 'B', '客户期望不能覆盖强制合规和安全。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-003', '团队连续三次 Sprint 未达 Goal，但 Velocity 上升。PM/敏捷领导最应关注？', '{"A":"只庆祝 Velocity","B":"与团队检查目标未达的根因、质量和价值，形成改进实验","C":"提高点数","D":"取消 Retrospective"}', 'Agile', 'Cross-cutting', 'Agile', '难', 'Vanity metric');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-003', 'B', 'Velocity 不是价值或目标达成的替代指标。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-004', '发起人要求 PM 隐瞒预测超支直到下一季度。PM 应？', '{"A":"遵从","B":"依据伦理和治理透明报告准确状态及恢复选项","C":"修改 AC","D":"删除成本基准"}', 'Business Environment', 'BE1', 'Predictive', '中', 'Ethics');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-004', 'B', '诚实、责任和治理要求准确透明。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-005', '合同目标已满足，但供应商提出未决索赔。项目可否直接关闭采购？', '{"A":"可以，产品已交付","B":"不应；需按合同和治理解决/记录索赔并完成采购收尾","C":"只需口头承诺","D":"删除索赔"}', 'Process', 'PR5/PR10', 'Predictive', '中', '交付 ≠ 合同收尾');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-005', 'B', '采购收尾包括未决索赔、付款、记录和正式确认。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-006', 'AI 自动生成周报，把未验证预测写成事实。最佳纠正是？', '{"A":"继续自动发送","B":"增加来源标注、验证、审批和不确定性表达","C":"停止所有 AI 永久使用","D":"隐藏模型版本"}', 'AI', 'Cross-cutting', 'All', '中', 'Prediction ≠ fact');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-006', 'B', '应按风险设置验证和人类监督，而非盲用或一刀切。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-007', '一位高权力低兴趣干系人突然反对项目。团队最先查看什么？', '{"A":"仅 WBS","B":"Stakeholder Register、参与策略和最近环境变化","C":"只看成本报告","D":"删除其姓名"}', 'People', 'P4/P5', 'All', '中', '分类会变化');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-007', 'B', '先了解期望、影响和变化，再调整参与。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-008', '项目完成 70%，新证据表明预期收益不再成立。最佳做法？', '{"A":"因已完成 70% 必须继续","B":"更新商业论证与选项，提交治理层价值决策","C":"隐藏证据","D":"增加范围制造收益"}', 'Business Environment', 'BE8', 'All', '难', 'Sunk cost fallacy');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-008', 'B', '沉没成本不应替代前瞻价值判断。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-009', '控制图出现连续七点在中心线同一侧，但仍在控制界限内。应怎样理解？', '{"A":"过程一定稳定","B":"存在非随机模式，应调查特殊原因","C":"产品必然不合格","D":"这是范围变更"}', 'Process', 'PR7', 'Predictive', '难', 'Control limit vs specification');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-009', 'B', '控制图不仅看越界，也看非随机模式。是否符合规格需另行判断。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-010', 'PO 与监管负责人对功能顺序有冲突。最合适？', '{"A":"PO 忽略法规","B":"把强制合规作为约束，与双方基于价值和风险重排 Backlog","C":"Scrum Master 独自定优先级","D":"开发人员隐藏需求"}', 'Agile', 'Cross-cutting', 'Agile', '难', 'PO 权限有治理边界');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-010', 'B', 'PO 管排序但不能绕过合规；需透明协作。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-011', '项目移交后运营团队不会处理关键告警。PM 应在关闭前？', '{"A":"只归档代码","B":"验证培训、运行手册、演练、权限和支持责任","C":"立即释放所有人员","D":"把告警设为低优先级"}', 'Process', 'PR10', 'All', '中', '文档 ≠ readiness');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-011', 'B', 'Transition readiness 要验证实际承接能力。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-012', '为达到可持续采购目标，团队选择本地供应商，但其质量能力未经验证。最佳做法？', '{"A":"可持续目标自动覆盖质量","B":"综合评估质量、风险、合规、全寿命价值并制定能力/合同措施","C":"只按距离决定","D":"取消可持续目标"}', 'Sustainability', 'Cross-cutting', 'All', '难', 'Single-metric optimization');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-012', 'B', '可持续性需与质量、风险和价值整合，不是单指标决策。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-013', '团队成员发现章程中的成功指标互相矛盾。PM first？', '{"A":"选择最容易的指标","B":"与发起人和关键干系人澄清并对齐可衡量标准","C":"等收尾再解释","D":"让 AI 随机选择"}', 'People', 'P1/P5', 'All', '中', '冲突指标不能拖延');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-013', 'B', '成功标准属于愿景、治理和价值基础，应尽早对齐。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-014', 'Sprint 中关键缺陷威胁 Sprint Goal。Developers 应？', '{"A":"等待下次 Sprint","B":"立即协作处理，与 PO 讨论范围/目标影响并保持透明","C":"让 PM 单独修复","D":"隐藏缺陷保证 Velocity"}', 'Agile', 'Cross-cutting', 'Agile', '中', '质量不能隐藏');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-014', 'B', '团队自管理质量，PO 提供价值/范围权衡，保持透明。');
INSERT INTO questions (id, stem, options_json, domain, task, approach, difficulty, trap) VALUES ('MOCK-A-015', '某风险概率低但一旦发生将造成严重人员伤害。仅按概率排序会怎样？', '{"A":"足够","B":"可能低估风险；应考虑影响、紧迫性、阈值和合规","C":"自动转为机会","D":"不需要所有人"}', 'Business Environment', 'BE2/BE5', 'All', '难', 'Probability-only bias');
INSERT INTO question_keys (question_id, answer, rationale) VALUES ('MOCK-A-015', 'B', '定性分析是多维的，高影响安全风险需符合阈值和合规。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-PRED-01', '医院影像中心改造', 'Process', 'Predictive', '医院必须在法定停机窗口内更换影像设备。施工范围稳定，但临时提出增加候诊区屏幕。', '["这是变更还是缺陷？","PM 的 first action？","哪些基准和风险需分析？"]', 'Change, Compliance, Schedule');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-PRED-01', '记录变更，分析范围/进度/成本/安全/运营停机影响，按授权变更控制；未批准前不实施。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-PRED-02', '数据中心关键路径', 'Process', 'Predictive', '两条网络路径之一总工期 38 天且浮动为零；设备到货延迟 4 天。', '["最可能的工期影响？","比较 Crashing 与 Fast Tracking。","应向谁报告什么？"]', 'Critical Path, Compression');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-PRED-02', '确认延迟落在关键路径和实际依赖上，再评估压缩成本与重叠风险，形成恢复选项并更新预测。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-PRED-03', '固定总价供应商', 'Process', 'Predictive', '固定总价合同的供应商称原材料上涨，要求额外付款，否则减配。', '["风险主要由谁承担？","先查看哪些合同事实？","何时升级？"]', 'Procurement, Quality');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-PRED-03', '先审查合同、变更条款、规格和履约证据；不可默许减配。按采购谈判与索赔路径处理，超权限再升级。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-PRED-04', '正式验收与运营移交', 'Process', 'Predictive', '系统通过测试，业务负责人未签验收，运营团队也没有管理员账号。发起人要求立即关闭。', '["哪些关闭条件未满足？","需要哪些证据？","收益责任如何移交？"]', 'Acceptance, Transition');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-PRED-04', '技术合格不足以关闭。取得正式验收，验证账号、培训、支持和运行准备，完成收尾并明确收益所有者。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-PRED-05', '安全法规变化', 'Business Environment', 'Predictive', '施工中法规立即提高高空作业标准，现有方案不合规。', '["是否先等 CCB？","如何处理紧急性与治理？","哪些记录更新？"]', 'Compliance, Change');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-PRED-05', '立即停止不安全/不合规活动并保护人员，同时评估影响、走紧急治理和变更，更新合规、风险、进度和沟通记录。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-AGILE-01', '支付产品新需求', 'Process', 'Agile', 'Sprint 第四天，销售要求加入大客户折扣功能，当前 Sprint Goal 是修复结算稳定性。', '["谁排序？","是否中断 Sprint？","如何保持价值透明？"]', 'PO, Backlog, Sprint Goal');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-AGILE-01', '新需求交给 PO 进入 Backlog。评估是否威胁或支持 Sprint Goal；不应由 PM 直接塞入。与销售透明沟通时机和价值。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-AGILE-02', 'Daily Scrum 变汇报会', 'People', 'Agile', '团队每天向经理逐人汇报，成员之间不协作，阻塞持续三天。', '["Daily Scrum 的目的？","Scrum Master 如何介入？","怎样验证改进？"]', 'Servant Leadership, Daily Scrum');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-AGILE-02', '辅导 Developers 围绕 Sprint Goal 检查进展、调整计划并协作清除阻塞；经理可通过透明工件获取状态。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-AGILE-03', 'DoD 被降低', 'Process', 'Agile', '为提高 Velocity，团队删除安全扫描和代码评审，点数显著上升。', '["指标是否改善？","有哪些风险？","Retrospective 应形成什么？"]', 'DoD, Metrics, Quality');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-AGILE-03', 'Velocity 被游戏化，质量和风险恶化。恢复/强化 DoD，分析根因并以价值、缺陷和流动共同度量。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-AGILE-04', '看板瓶颈', 'Process', 'Agile', '测试列 WIP 已达上限，开发列仍不断开始新任务。', '["团队下一步？","为什么利用率思维会伤害流动？","用什么指标验证？"]', 'Kanban, WIP');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-AGILE-04', '停止拉取新开发，跨职能帮助测试或移除瓶颈；观察 Cycle Time、Throughput 和阻塞。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-AGILE-05', 'Review 与 Retro 混淆', 'People', 'Agile', '团队在 Sprint Review 内部讨论成员配合问题，没有邀请关键用户。', '["两个事件焦点分别是什么？","如何重设参与？","产品反馈在哪里处理？"]', 'Review, Retrospective');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-AGILE-05', 'Review 与干系人检查产品和环境并调整 Backlog；Retro 由团队改进工作方式。分别恢复目的。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-HYB-01', '智慧工厂', 'Process', 'Hybrid', '厂房改造必须按固定里程碑施工，AI 排产界面需每两周验证。', '["如何拆分方法？","主要接口风险？","怎样统一报告？"]', 'Hybrid, Interfaces, AI');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-HYB-01', '施工用预测型，界面用敏捷；统一安全窗口、数据接口、依赖、集成测试和价值里程碑。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-HYB-02', '政府门户', 'Business Environment', 'Hybrid', '合同要求阶段门和固定预算，公众服务功能需求仍在探索。', '["哪些内容基准化？","哪些进入 Backlog？","变化如何过治理？"]', 'Governance, Backlog');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-HYB-02', '法规、预算、阶段证据和高层范围基准化；功能细节用 Backlog 迭代。重大基准影响走治理，并将增量证据映射阶段门。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-HYB-03', '多供应商集成', 'Process', 'Hybrid', '硬件供应商按月报告百分比，软件团队按 Sprint 交付，接口规格不断变化。', '["为什么双重报告不足？","建立哪些共同工件？","如何管理变更？"]', 'Vendor, Integration');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-HYB-03', '建立共同接口清单、集成里程碑、风险和决策日志；报告映射到可验证成果，不直接换算 Story Point。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-HYB-04', '滚动式规划误解', 'People', 'Hybrid', '治理层认为远期计划不详细就是团队没有计划。', '["如何解释 Rolling Wave？","哪些长期内容仍需清晰？","怎样建立信任？"]', 'Rolling Wave, Communication');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-HYB-04', '近期详细、远期高层是面对不确定性的计划策略；长期愿景、约束、价值、里程碑和风险仍需透明，并定期细化。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-HYB-05', '敏捷绕过合规', 'Business Environment', 'Hybrid', '团队称自己敏捷，因此不记录隐私影响评估。', '["哪里错误？","如何裁剪而非删除证据？","谁负责监督？"]', 'Compliance, Tailoring');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-HYB-05', 'Agile 不能绕过合规。将合规验收、证据和审查嵌入 Backlog/DoD/治理，按风险裁剪文档。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-FUT-01', 'AI 风险预测', 'AI', 'Hybrid', '模型预测供应商违约概率 82%，但训练数据来自另一个国家。', '["验证什么？","是否立即终止合同？","如何表达不确定性？"]', 'AI Validation, Procurement');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-FUT-01', '验证数据适用性、偏差、模型版本和基准；结合合同事实与专家判断，不自动行动。记录概率、限制和人类决定。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-FUT-02', '客户数据摘要', 'AI', 'Agile', '团队用生成式 AI 总结访谈，摘要漏掉无障碍用户的核心需求。', '["风险类型？","如何纠正？","Backlog 受到什么影响？"]', 'Bias, Stakeholders');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-FUT-02', '这是代表性和偏差风险。回查原始证据、纳入受影响群体、验证摘要并纠正 Backlog 优先级。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-FUT-03', '低碳材料选择', 'Sustainability', 'Predictive', '材料 A 便宜但运营能耗高；B 初始贵 12% 但十年排放和维护低。', '["比较框架？","哪些指标？","预算阈值如何处理？"]', 'Life-cycle, Finance');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-FUT-03', '用全生命周期成本、碳、可靠性、合规和价值比较；若影响批准基准，提交治理决策。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-FUT-04', '供应链劳工风险', 'Sustainability', 'All', '关键供应商价格最低，但审计发现高概率劳工违规。', '["仅因低价能否选择？","要采取什么尽调？","如何记录风险与合同要求？"]', 'Social Impact, Procurement');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-FUT-04', '不能只看价格。验证事实，评估合规/声誉/交付影响，设置准入、整改、审计和退出条款。');
INSERT INTO cases (id, title, domain, approach, scenario, prompts_json, tags) VALUES ('CASE-FUT-05', 'AI 自动批准变更', 'AI', 'Predictive', '公司计划让 AI 对低于 2% 成本的变更自动批准。', '["需要哪些治理边界？","哪些变更不能仅按成本判断？","如何监控？"]', 'AI Governance, Change');
INSERT INTO case_keys (case_id, guide) VALUES ('CASE-FUT-05', '按影响而非成本单一阈值定义权限；安全、隐私、范围、价值等高影响变更保留人工审批。记录模型、理由、异常和回退。');
INSERT INTO question_knowledge (question_id, knowledge_id, role, weight, reason, reviewed) VALUES ('KP-FOUND-001', 'KP-002', 'primary', 0.8, '判断限时但重复维持业务的运营活动', 1);
INSERT INTO question_knowledge (question_id, knowledge_id, role, weight, reason, reviewed) VALUES ('KP-FOUND-001', 'KP-001', 'secondary', 0.2, '同时检验项目与运营边界', 1);
INSERT INTO question_knowledge (question_id, knowledge_id, role, weight, reason, reviewed) VALUES ('KP-FOUND-002', 'KP-001', 'primary', 0.8, '判断创造独特成果并完成移交的项目', 1);
INSERT INTO question_knowledge (question_id, knowledge_id, role, weight, reason, reviewed) VALUES ('KP-FOUND-002', 'KP-002', 'secondary', 0.2, '同时检验项目与运营边界', 1);
INSERT INTO question_knowledge (question_id, knowledge_id, role, weight, reason, reviewed) VALUES ('KP-FOUND-003', 'KP-001', 'primary', 0.8, '辨析重复举办与单次项目的独特性', 1);
